def has_relevant_docs(query: str, db, k: int = 3, threshold: float = 0.2) -> bool:
    """
    Perform a lightweight similarity search and return True if any result
    has a similarity score above the threshold.
    The Chroma similarity_search returns Document objects; we approximate relevance
    by checking the presence of any result (since exact scores aren't exposed).
    """
    try:
        results = db.similarity_search(query, k=k)
        return len(results) > 0
    except Exception as e:
        logging.warning(f"Relevance check failed: {e}")
        return False


